560	    base.fillStyle(0x81c784, 0.6);  base.fillEllipse(0, -2 * LS, 16 * LS, 5 * LS);
561	    base.setPosition(cx, cy + 2);
562	    scene.tweens.add({ targets: base, scale: 1, duration: 220, ease: 'Back.easeOut' });
563	
564	    // 금빛 중앙 글로우
