566	    glow.fillStyle(0xffd700, 0.20); glow.fillCircle(0, 0, 30 * LS);
567	    glow.fillStyle(0xffe082, 0.35); glow.fillCircle(0, 0, 18 * LS);
568	    glow.fillStyle(0xffffff, 0.55); glow.fillCircle(0, 0,  8 * LS);
569	    glow.setPosition(cx, cy - 14 * LS);
570	    scene.tweens.add({ targets: glow, scale: 1, duration: 320, ease: 'Back.easeOut' });
571	
572	    // sin(t*π) 곡선으로 양 끝 뾰족한 꽃잎 폴리곤
573	    const petalPts = (w: number, h: number): { x: number; y: number }[] => {
574	      const N = 16;
575	      const pts: { x: number; y: number }[] = [];
576	      for (let i = 0; i <= N; i++) {
577	        const t = i / N;
578	        pts.push({ x:  (w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
579	      }
580	      for (let i = N - 1; i >= 0; i--) {
581	        const t = i / N;
582	        pts.push({ x: -(w / 2) * Math.sin(t * Math.PI), y: h / 2 - t * h });
583	      }
584	      return pts;
585	    };
586	
587	    // 꽃잎: 바닥 한 점에서 각도 방향으로 뻗어나가는 옆면 형태
588	    const petalGfxs: Phaser.GameObjects.Graphics[] = [];
