601	      g.fillStyle(0xffd700, 0.18);
602	      g.fillEllipse(0, -(sh * 0.3), sw * 0.55, sh * 0.22);
603	      g.setPosition(ppx, ppy).setRotation(rotRad).setScale(0);
604	
605	      scene.tweens.add({ targets: g, scale: 1, delay: idx * 40, duration: 280, ease: 'Back.easeOut' });
606	      petalGfxs.push(g);
