616	      targets: stamen, scale: 1,
617	      delay: LOTUS_DEFS.length * 40 - 20, duration: 220, ease: 'Back.easeOut',
618	    });
619	
620	    // 900ms 후 조용히 페이드아웃
621	    const allObjs: Phaser.GameObjects.Graphics[] = [...petalGfxs, glow, base, stamen];
622	    scene.time.delayedCall(900, () => {
623	      if (!scene.sys.isActive()) return;
