private _strikeRedLightning(api: GameSceneAPI): void {
  const { scene, player } = api;
  const tx = player.x;
  const ty = player.y;

  scene.cameras.main.flash(250, 120, 0, 0, true);

  const g = scene.add.graphics().setDepth(310);

  // 공통 줄기(trunk): 화면 상단 → 플레이어까지의 약 70% 지점
  // 끝단 분기(branches): 70% 지점에서 1~3개 줄기로 나뉘어 플레이어에 닿음
  const makeRedBranches = (startX: number) => {
    const trunk: { x: number; y: number }[] = [{ x: startX, y: -10 }];
    for (let i = 1; i < 10; i++) {
      const t = (i / 10) * 0.70;
      const spread = 55 * (1 - t * 0.8);
      trunk.push({ x: tx + Phaser.Math.Between(-spread, spread), y: (ty + 20) * t - 10 });
    }
    const splitX = trunk[trunk.length - 1]!.x;
    const splitY = (ty + 20) * 0.70 - 10;
    trunk.push({ x: splitX, y: splitY });

    const branchCount = Phaser.Math.Between(1, 3);
    const endOffsets: number[][] = [[0], [-22, 22], [-30, 0, 30]];
    const offsets = endOffsets[branchCount - 1]!;

    const branches = offsets.map(off => {
      const endX = tx + off + Phaser.Math.Between(-8, 8);
      const pts: { x: number; y: number }[] = [{ x: splitX, y: splitY }];
      for (let i = 1; i <= 3; i++) {
        const t = i / 3;
        pts.push({
          x: splitX + (endX - splitX) * t + Phaser.Math.Between(-10, 10),
          y: splitY + ((ty + 8) - splitY) * t,
        });
      }
      return pts;
    });

    return { trunk, branches };
  };

  const drawRed = () => {
    g.clear();
    const { trunk, branches } = makeRedBranches(tx + Phaser.Math.Between(-20, 20));

    // 줄기 레이어
    g.lineStyle(16, 0x000000, 0.55); this._drawPolyline(g, trunk);
    g.lineStyle(10, 0x1a0000, 0.50); this._drawPolyline(g, trunk);
    g.lineStyle(6,  0x550000, 0.60); this._drawPolyline(g, trunk);
    g.lineStyle(3,  0xaa1100, 0.90); this._drawPolyline(g, trunk);
    g.lineStyle(1.5, 0xff3311, 1.00); this._drawPolyline(g, trunk);

    // 끝단 분기 레이어 (줄기보다 약간 얇게)
    for (const bPts of branches) {
      g.lineStyle(12, 0x000000, 0.45); this._drawPolyline(g, bPts);
      g.lineStyle(7,  0x1a0000, 0.45); this._drawPolyline(g, bPts);
      g.lineStyle(4,  0x550000, 0.55); this._drawPolyline(g, bPts);
      g.lineStyle(2,  0xaa1100, 0.90); this._drawPolyline(g, bPts);
      g.lineStyle(1,  0xff3311, 1.00); this._drawPolyline(g, bPts);
    }
  };

